package database

import (
	"strconv"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/hkjang/igame/migrations"
)

func sqlFiles(names ...string) fstest.MapFS {
	files := fstest.MapFS{}
	for _, name := range names {
		files[name] = &fstest.MapFile{Data: []byte("SELECT 1;")}
	}
	return files
}

// The migrations are applied in the order they are numbered, and the tenth one
// is where sorting the names stops agreeing with that: "10_" sorts before
// "002_". Applying a brand new migration second, against a database that is
// already live, is a broken deployment that only happens once the tenth file
// exists.
func TestATenthMigrationIsAppliedAfterTheNinthAndNotSecond(t *testing.T) {
	names, err := migrationNames(sqlFiles("001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"))
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	want := []string{"001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"}
	if strings.Join(names, ",") != strings.Join(want, ",") {
		t.Fatalf("migrations run as %v, want %v", names, want)
	}
}

// Two branches that each add "010_" merge cleanly and leave the order of the
// two schema changes up to whatever the file system reports first. Refusing to
// start says so once instead of applying them differently on different hosts.
func TestTwoMigrationsSharingANumberAreRefused(t *testing.T) {
	_, err := migrationNames(sqlFiles("001_initial.sql", "010_ranking.sql", "010_replay.sql"))
	if err == nil {
		t.Fatal("two migrations numbered 010 were accepted; their order is left to the file system")
	}
	if !strings.Contains(err.Error(), "010_ranking.sql") || !strings.Contains(err.Error(), "010_replay.sql") {
		t.Fatalf("the error does not name both files: %v", err)
	}
}

// A file that carries no number has no place in the sequence, so guessing one
// would apply it at an arbitrary point. It is reported instead.
func TestAMigrationWithoutANumberIsRefused(t *testing.T) {
	for _, name := range []string{"initial.sql", "v2_extended.sql", "003 realmguard.sql"} {
		if _, err := migrationNames(sqlFiles("001_initial.sql", name)); err == nil {
			t.Fatalf("%q was accepted as a migration despite not being numbered", name)
		}
	}
}

// Only the .sql files are schema migrations; migrations.go lives beside them.
func TestNonSQLFilesAreNotTreatedAsMigrations(t *testing.T) {
	files := sqlFiles("001_initial.sql")
	files["migrations.go"] = &fstest.MapFile{Data: []byte("package migrations")}
	files["README.md"] = &fstest.MapFile{Data: []byte("# schema")}
	names, err := migrationNames(files)
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	if len(names) != 1 || names[0] != "001_initial.sql" {
		t.Fatalf("migrations are %v, want only 001_initial.sql", names)
	}
}

// The shipped migrations have to satisfy the convention the loader enforces,
// and their numbers have to run 1, 2, 3 ... with no gap: a gap means a file
// that a deployed database has already applied went missing from the tree.
func TestTheShippedMigrationsAreNumberedFromOneWithoutGaps(t *testing.T) {
	names, err := migrationNames(migrations.Files)
	if err != nil {
		t.Fatalf("the shipped migrations do not follow the naming convention: %v", err)
	}
	if len(names) == 0 {
		t.Fatal("no migrations are embedded; a fresh database would come up with no schema")
	}
	for i, name := range names {
		number, err := strconv.Atoi(migrationFileName.FindStringSubmatch(name)[1])
		if err != nil {
			t.Fatalf("migration %s has an unreadable number: %v", name, err)
		}
		if number != i+1 {
			t.Fatalf("migration %s is numbered %d but sits at position %d; a migration is missing", name, number, i+1)
		}
	}
}
package api

import (
	"context"
	"crypto/sha256"
	"net/http"
	"net/http/httptest"
	"strconv"
	"testing"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5/pgxpool"
)

// Whether the session a player is in right now counts towards the daily play
// limit is decided by a SQL sum against the database clock, so these tests need
// a real server. They are skipped when IGAME_TEST_DSN is unset; `make test-db
// DSN=...` runs them.

// openSessionAge is how long an open session has been running in these tests.
// The database clock decides how much an open session has accrued, so the
// instant it started has to be real rather than invented.
const openSessionAge = 5 * time.Minute

// insertTestGame creates a game the calling test owns and removes again.
func insertTestGame(t *testing.T, pool *pgxpool.Pool, slug string) uuid.UUID {
	t.Helper()
	var id uuid.UUID
	if err := pool.QueryRow(context.Background(), `INSERT INTO games(slug,name,game_url,status) VALUES($1,'Play limit test','/games/limit','active') RETURNING id`, slug).Scan(&id); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { _, _ = pool.Exec(context.Background(), `DELETE FROM games WHERE id=$1`, id) })
	return id
}

// insertTestPlaySession records one session for the pair. Status 'active' with
// no duration is the session a player has open right now.
func insertTestPlaySession(t *testing.T, pool *pgxpool.Pool, userID, gameID uuid.UUID, status string, startedAt time.Time, duration *int64) {
	t.Helper()
	hash := sha256.Sum256([]byte(uuid.NewString()))
	if _, err := pool.Exec(context.Background(), `INSERT INTO game_sessions(user_id,game_id,session_token_hash,status,started_at,duration_ms) VALUES($1,$2,$3,$4,$5,$6)`, userID, gameID, hash[:], status, startedAt, duration); err != nil {
		t.Fatal(err)
	}
}

// serviceDay reads the database clock and reports the start of the service day
// containing it. The policy below names Asia/Seoul, which is +09:00 the year
// round and is also what playAllowed falls back to when the zone cannot be
// loaded, so a fixed offset names the same boundary either way.
//
// A session cannot have been open since before the service day began, so a run
// that lands in the first minutes of a Seoul day has nowhere to put one and
// says so rather than asserting something weaker.
func serviceDay(t *testing.T, pool *pgxpool.Pool) (now, dayStart time.Time) {
	t.Helper()
	if err := pool.QueryRow(context.Background(), `SELECT clock_timestamp()`).Scan(&now); err != nil {
		t.Fatal(err)
	}
	local := now.In(time.FixedZone("KST", 9*60*60))
	dayStart = time.Date(local.Year(), local.Month(), local.Day(), 0, 0, 0, 0, local.Location())
	if local.Sub(dayStart) < openSessionAge {
		t.Skipf("the service day began %s ago, which leaves no room for a session open for %s", local.Sub(dayStart), openSessionAge)
	}
	return now, dayStart
}

// playLimitServer decides a daily limit for the slug against the real pool,
// with the server clock pinned to the database clock so the service day the
// policy measures is the one the sessions were placed in.
func playLimitServer(t *testing.T, pool *pgxpool.Pool, slug string, limitMinutes int, now time.Time) *Server {
	t.Helper()
	policy := `{"enabled":true,"windows":[],"daily_limits":{"` + slug + `":` + strconv.Itoa(limitMinutes) + `}}`
	s := &Server{DB: pool, Now: func() time.Time { return now }}
	s.storeSetting("play_policy", settingEntry{raw: []byte(policy), expires: time.Now().Add(time.Hour)})
	s.storeSetting("service", settingEntry{raw: []byte(`{"timezone":"Asia/Seoul"}`), expires: time.Now().Add(time.Hour)})
	return s
}

func askPlayLimit(t *testing.T, s *Server, userID, gameID uuid.UUID, slug string) (bool, string) {
	t.Helper()
	r := httptest.NewRequest(http.MethodPost, "/api/v1/sessions", nil)
	r = r.WithContext(context.WithValue(r.Context(), principalKey, Principal{UserID: userID, Role: "user", AuthType: "session"}))
	allowed, denial, err := s.playAllowed(r, gameID, slug)
	if err != nil {
		t.Fatal(err)
	}
	return allowed, denial
}

// playLimitFixture sets up one user, one game and one server for a limit.
func playLimitFixture(t *testing.T, limitMinutes int) (*Server, *pgxpool.Pool, uuid.UUID, uuid.UUID, string, time.Time) {
	t.Helper()
	pool := migratedPool(t)
	now, dayStart := serviceDay(t, pool)
	userID := insertTestUser(t, pool, "user")
	slug := "play-limit-" + uuid.NewString()[:8]
	gameID := insertTestGame(t, pool, slug)
	return playLimitServer(t, pool, slug, limitMinutes, now), pool, userID, gameID, slug, dayStart
}

func TestPlayLimitCountsTheSessionStillOpen(t *testing.T) {
	// duration_ms is written only when a session ends, so summing it alone
	// counted the session open right now as no play at all. The limit is checked
	// as a session starts, and the session open at that moment is exactly the one
	// the sum dropped, so a player got one whole session past the limit each day.
	s, pool, userID, gameID, slug, _ := playLimitFixture(t, 1)

	insertTestPlaySession(t, pool, userID, gameID, "active", s.Now().Add(-openSessionAge), nil)

	allowed, denial := askPlayLimit(t, s, userID, gameID, slug)
	if allowed {
		t.Fatalf("a session open for %s did not count towards a one minute limit", openSessionAge)
	}
	if denial != "daily play limit reached" {
		t.Fatalf("denial = %q, want the daily limit", denial)
	}
}

func TestPlayLimitLeavesRoomBelowTheLimit(t *testing.T) {
	// Counting the open session must not close the door early: a player who is
	// still under the limit gets to start another session.
	s, pool, userID, gameID, slug, _ := playLimitFixture(t, 60)

	finished := int64(20 * 60000)
	insertTestPlaySession(t, pool, userID, gameID, "finished", s.Now().Add(-time.Hour), &finished)
	insertTestPlaySession(t, pool, userID, gameID, "active", s.Now().Add(-openSessionAge), nil)

	if allowed, denial := askPlayLimit(t, s, userID, gameID, slug); !allowed {
		t.Fatalf("well under an hour of a sixty minute limit was refused: %q", denial)
	}
}

func TestPlayLimitIgnoresSessionsFromBeforeTheServiceDay(t *testing.T) {
	// The limit is a daily one and the day is the service time zone's, so a
	// session left open yesterday must not spend today's allowance.
	s, pool, userID, gameID, slug, dayStart := playLimitFixture(t, 1)

	insertTestPlaySession(t, pool, userID, gameID, "active", dayStart.Add(-time.Hour), nil)

	if allowed, denial := askPlayLimit(t, s, userID, gameID, slug); !allowed {
		t.Fatalf("a session from before the service day was charged to today: %q", denial)
	}
}

func TestPlayLimitCountsAClosedSessionWithoutADurationAsNothing(t *testing.T) {
	// A session that is over stops accruing time even when no duration was ever
	// recorded for it, so the clause that measures open sessions must not reach
	// closed ones.
	s, pool, userID, gameID, slug, _ := playLimitFixture(t, 1)

	insertTestPlaySession(t, pool, userID, gameID, "abandoned", s.Now().Add(-openSessionAge), nil)

	if allowed, denial := askPlayLimit(t, s, userID, gameID, slug); !allowed {
		t.Fatalf("a closed session with no duration was billed for the time since it started: %q", denial)
	}
}
# 릴리스

## 불변 계약

- 서비스명: `igame`
- 이미지: `igame:v<VERSION>`
- 대상 platform: `linux/amd64`
- GitHub Release asset: `igame-v<VERSION>.tar.gz` 단 하나
- asset 내용: `docker save igame:v<VERSION> | gzip` 출력 자체
- `VERSION` 파일에는 앞의 `v` 없이 semantic version 기록
- 런타임 환경변수: `POSTGRES_DSN`, `BOOTSTRAP_ADMIN`, `BOOTSTRAP_ADMIN_PASSWORD`, `ENCRYPTION_KEY`만 사용

SBOM과 checksum은 CI에서 생성·검증하고 workflow evidence artifact와 job summary에 남깁니다. 별도 release asset으로 올리거나 이미지 archive 내부에 삽입하지 않습니다. 일반 CI와 Release workflow는 Web·SDK lockfile을 `npm audit --audit-level=low`로 검사하고, 정확히 고정한 `govulncheck v1.6.0`으로 reachable Go 취약점을 검사합니다. SDK build chain은 Windows 개발 서버 경로 탐색 advisory를 피하도록 esbuild `0.27.2`를 root override로 고정합니다. Builder는 `golang:1.26.6-alpine3.23`이며, 최종 이미지는 package manager와 shell이 없는 `scratch`입니다. 최종 이미지에는 정적 `/app/igame`, CA 신뢰 번들, 오프라인 검토용 license metadata만 포함합니다. 두 workflow 모두 고정된 Anchore scan action과 Grype `v0.117.0`으로 최종 이미지를 검사해 High/Critical 발견 시 중단하며, `io.igame.build.go-version` 라벨과 추출한 `/app/igame`의 `go version -m`이 모두 `go1.26.6`인지 확인합니다. 이미지 `User`는 `10001:10001`이며 Compose는 read-only filesystem, `cap_drop: ALL`, `no-new-privileges` 계약을 유지합니다. Docker healthcheck는 shell utility 대신 `/app/igame healthcheck`를 실행합니다.


관리자 설정 왕복은 `scripts/smoke-settings.sh`가 검사합니다. 설정 조회가 돌려준 값을 그대로 저장했을 때 받아들여지는지, 설정 값 안에 `_configured` 같은 파생 field가 섞이지 않는지, secret이 저장된 채로 유지되면서도 절대 다시 읽히지 않는지, 그러면서 모르는 field는 여전히 400으로 거부되는지를 확인합니다. Keycloak OIDC 설정이 저장되지 않던 원인이 정확히 이 왕복이 깨진 것이었습니다.

인가 경계는 `scripts/smoke-authz.sh`가 따로 검사합니다. API key가 자기 범위 안에서는 응답하고 그 밖은 거부되는지, 키로 키를 관리할 수 없는지, 거부가 감사 로그에 `access.denied`로 기록되는지, 폐기한 키가 다음 요청부터 막히는지, 세션을 가진 채 외부 Origin에서 오는 쓰기가 거부되는지를 확인합니다.

`v0.6.0`의 RealmGuard 결과 검증은 서버가 전투를 재현합니다. 브라우저 kernel과 Go 검증기가 갈라지면 정상 플레이가 전부 거부되므로, 두 구현은 저장소에 커밋된 replay vector와 콘텐츠 투영 fixture로 묶여 있습니다. 규칙이나 밸런스를 바꾼 뒤에는 `UPDATE_KERNEL_VECTORS=1 npx vitest run src/games/realmguard/kernel`로 vector·투영 digest·릴리스 smoke 전투를 다시 생성하고, `go test ./internal/...`과 web test가 모두 통과하는지 확인합니다. 재생성하지 않으면 Go test가 먼저 실패합니다.

RealmGuard 회귀 smoke는 실제 전투 하나를 끝까지 제출합니다. 재현된 전투는 세션이 실제로 그만한 시간을 가졌을 때만 인정되므로, smoke는 시뮬레이션 길이의 절반만큼 실제로 기다립니다. 현재 smoke 전투는 약 262초 분량이며 스크립트 전체는 2~3분이 걸립니다.

Production build는 RealmGuard와 Defense Series source가 locked Phaser dependency를 실제로 import하는지, compiled asset에 네 게임 route/content가 존재하는지, `index.html`이 원격 script/stylesheet를 참조하지 않는지를 검사합니다. Web과 SDK package version은 root `VERSION`과 같아야 합니다. 최종 이미지에는 locked web package manifest/lock을 `/licenses/web`, SDK manifest/lock을 `/licenses/sdk/gamehub-js`, Phaser package metadata와 MIT license를 `/licenses/phaser`에 보관합니다. SPDX SBOM에서 정확한 Phaser·`@igame/gamehub-js` version이 식별되지 않으면 Release workflow를 중단합니다. `003_realmguard.sql`, `004_realmguard_attestation.sql`과 Defense Series schema/seed migration을 포함한 SQL migration은 Go binary에 embed됩니다. fresh DB에서 세 Defense content pack이 각각 하나의 published snapshot으로 생성되고, 기존 RealmGuard 경제 필드는 `bigint`를 유지해야 합니다.

서비스 릴리스와 게임 콘텐츠는 서로 다른 수명 주기를 가집니다. `igame:v0.7.17`에는 RealmGuard 콘텐츠 `0.3.1`과 Defense Series 콘텐츠 `0.4.0`이 함께 들어갑니다. Web·SDK·이미지 버전은 root `VERSION`을 따르지만, 기존 게임 콘텐츠 버전을 서비스 버전으로 덮어쓰지 않습니다. 공식 세션은 각 게임 public config에서 읽은 immutable snapshot UUID를 사용합니다.

콘텐츠의 `asset_version`은 해당 immutable snapshot이 소유한 자산 metadata와 telemetry 계약을 나타냅니다. 영웅 선택 카드, HUD와 코드 생성 전장 배경 같은 서비스 공통 renderer는 서비스 버전을 따르므로, 보존된 custom snapshot은 기존 `asset_version`을 보고하면서도 `v0.7.17`의 공통 UI 개선을 사용합니다. 적·타워의 코드 생성 외형도 콘텐츠의 id와 특성에서 파생되는 공통 renderer이므로 새 콘텐츠 version을 요구하지 않습니다. 운영자가 snapshot 자체의 자산 계약을 바꿀 때만 새 콘텐츠 버전을 게시합니다.

## 매뉴얼 PDF 재생성

`docs/`의 두 PDF는 `docs/cru-manual.md`와 `docs/architecture.md`에서 생성합니다. 이전에는 생성 파이프라인이 저장소에 없어 제품이 바뀌어도 다시 만들 수 없었습니다. 사용자 가이드와 관리자 가이드는 이 파이프라인이 아니라 화면 캡처를 함께 싣는 공용 가이드 도구로 만듭니다 — [사용자 가이드](USER_GUIDE.md) 참조.

```bash
make docs-pdf
```

Release browser gate와 같은 `mcr.microsoft.com/playwright:v1.55.0-noble` 컨테이너에서 Chromium 인쇄로 만듭니다. Playwright는 여기서도 repository dependency가 아니라 컨테이너 안에서만 설치합니다. 컨테이너에는 한글 글꼴이 없어 빌드 시 `fonts-noto-cjk`를 설치하며, 렌더링된 page가 외부 자원을 참조하면 인쇄를 중단합니다. 표지의 서비스 버전은 root `VERSION`을 따릅니다. 발행일은 기본적으로 빌드 당일이며 `DOCS_PDF_DATE=YYYY-MM-DD`로 고정할 수 있습니다.

## 로컬 후보 생성

Docker daemon을 준비한 다음 실행합니다. Syft가 있으면 SPDX JSON도 만들고, 없으면 단일 archive와 그 checksum을 만들며 경고합니다. GitHub CI에서는 Syft가 필수로 설치됩니다.

```bash
make test
make check-offline-bundle
make release
ls -lh dist/
bash ./scripts/verify-release.sh dist/igame-v$(cat VERSION).tar.gz
```

검증기는 gzip 무결성, Docker `manifest.json`, 보존된 `igame:v<version>` RepoTag와 checksum을 확인합니다. 동일 태그를 먼저 제거한 깨끗한 검증 환경에서 다음 load/smoke test도 수행합니다.

```bash
docker image rm "igame:v$(cat VERSION)"
gzip -dc dist/igame-v$(cat VERSION).tar.gz | docker load
docker image inspect "igame:v$(cat VERSION)"
```

Release workflow는 clean-load한 후보 이미지의 API smoke 직후, 앱 컨테이너를 정리하기 전에 Playwright `v1.55.0-noble` 컨테이너로 브라우저 gate를 자동 실행합니다. npm package도 `playwright@1.55.0`으로 정확히 고정하며 설치 또는 browser smoke가 실패하면 Release 게시를 중단합니다. Playwright는 제품 이미지나 repository dependency에 들어가지 않습니다. 아래 명령은 같은 gate를 QA host에서 수동 재현하는 방법입니다. 서비스 페이지가 로그인부터 RealmGuard와 Defense Series 세 게임 canvas, 교육 선택, 각 Designer/Studio와 연습 preview의 deep refresh까지 외부 HTTP 요청·console/page/request 오류 없이 동작하는지 검사합니다. 편집 화면은 앞선 API smoke가 남긴 editable draft를 반드시 열어 유효한 JSON과 활성화된 저장 버튼을 확인하며, invalid JSON 또는 빈 데이터 상태가 렌더링되면 실패합니다. 마지막으로 포털·관리자 20개 route에 axe-core 접근성 검사를 실행해 serious·critical 위반이 하나라도 있으면 실패하며, axe가 그라디언트·겹침 때문에 판단을 보류한 텍스트는 실제 렌더된 픽셀에서 대비를 측정해 기준 미달이면 실패합니다. 같은 20개 route를 1280·900·768px과 독자 기본 글꼴 2배에서 다시 훑어 가로 넘침을 검사하고, 4개 route는 키보드 Tab으로 모든 정지 지점에 포커스 표시가 보이는지 확인합니다.

```bash
export IGAME_BASE_URL='http://127.0.0.1:8080'
export IGAME_USERNAME='admin'
export IGAME_REQUIRE_DESIGNER_DRAFT=true
export IGAME_REQUIRE_DEFENSE_DRAFT=true
mkdir -p /tmp/igame-v03-screenshots
read -r -s -p 'Bootstrap password: ' IGAME_PASSWORD; export IGAME_PASSWORD
docker run --rm --network host \
  -e IGAME_BASE_URL -e IGAME_USERNAME -e IGAME_PASSWORD -e IGAME_REQUIRE_DESIGNER_DRAFT -e IGAME_REQUIRE_DEFENSE_DRAFT \
  -e IGAME_SCREENSHOT_DIR=/screenshots \
  -e PLAYWRIGHT_SKIP_BROWSER_DOWNLOAD=1 \
  -v /tmp/igame-v03-screenshots:/screenshots \
  -v "$PWD:/work:ro" -w /tmp \
  mcr.microsoft.com/playwright:v1.55.0-noble \
  bash -lc 'mkdir -p browser-smoke && cd browser-smoke && npm init -y >/dev/null && npm install --silent --no-save playwright@1.55.0 @axe-core/playwright@4.13.0 pngjs@7.0.0 && node /work/scripts/browser-smoke.mjs'
unset IGAME_PASSWORD
```

`/tmp/igame-v03-screenshots`에는 홈, 세 Defense 전장/교육·AI HUD, Content Studio의 로컬 검수 이미지가 남습니다. 이 증적은 사람이 시각 검수할 때만 사용하며 Docker image archive나 GitHub Release asset에 포함하지 않습니다.

## GitHub

`.github/workflows/release.yml`은 다음 진입점을 지원합니다.

- `v*` tag push
- Actions의 수동 실행(`version` 입력)

tag는 반드시 `v$(cat VERSION)`과 같아야 합니다. workflow는 test, RealmGuard/Defense Series/Phaser offline bundle, image build, SBOM의 Phaser 식별, archive 구조, clean-daemon load, PostgreSQL readiness, Bootstrap 로그인·비밀번호 회전과 주요 관리자 API를 검증합니다. 이미지가 fresh DB에 migration을 적용한 직후 published seed validator도 다시 실행합니다. RealmGuard의 기존 권위 결과·telemetry·Designer 회귀 smoke를 그대로 수행한 뒤 Defense Series smoke를 추가로 실행합니다. Defense smoke는 세 slug의 published config/version/progress, `defense_content_version_id` 누락 428·stale 409·정상 pin, 전용 결과/랭킹과 일반 score/ranking 우회 차단, 4 KiB ledger/content budget, 세 난이도의 실제 검증 결과, 교육 이벤트 답변, AI 자원 소진, 업적과 학습 결과, published UUID별 progress/ranking/report 격리, Studio `If-Match` 428/409, policy/source rollback Draft, Test/연습 preview/승인/반려/게시, telemetry와 learning report를 fresh DB에서 확인합니다. 승인 정책을 켠 경우 Manager 검토는 작성자와 같은 비어 있지 않은 team에서만 허용되며, 설정이 꺼진 경우 검토 단계를 만들지 않는 것도 확인합니다. 이 검증을 마친 뒤 GitHub Release를 생성하거나 갱신하고 오직 `.tar.gz` 하나만 asset으로 게시합니다. archive와 SBOM SHA-256은 Release 본문과 job summary에, SBOM 및 checksum 파일은 보존 기간이 정해진 workflow evidence에 기록합니다.

권장 순서:

```bash
version="$(cat VERSION)"
git tag -s "v${version}" -m "igame v${version}"
git push origin "v${version}"
```

보호 규칙으로 signed tag, 승인된 environment, Actions 변경 review를 요구하는 것이 좋습니다. Release workflow에서 외부 registry로 이미지를 push하지 않습니다.
#!/usr/bin/env bash
set -Eeuo pipefail

readonly SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)"
readonly REPO_DIR="$(cd -- "${SCRIPT_DIR}/.." && pwd)"
readonly VERSION="$(tr -d '[:space:]' < "${REPO_DIR}/VERSION")"
readonly COMPOSE_FILE="${REPO_DIR}/docker-compose.yml"
readonly ENV_EXAMPLE="${REPO_DIR}/.env.example"
readonly WEB_PACKAGE="${REPO_DIR}/web/package.json"
readonly WEB_LOCK="${REPO_DIR}/web/package-lock.json"
