readonly SDK_LOCK="${REPO_DIR}/sdk/gamehub-js/package-lock.json"

if ! grep -Fqx 'go 1.26.6' "${REPO_DIR}/go.mod" \
  || ! grep -Fq 'github.com/coreos/go-oidc/v3 v3.20.0' "${REPO_DIR}/go.mod" \
