package database

import (
	"context"
	"crypto/sha256"
	"fmt"
	"io/fs"
	"regexp"
	"sort"
	"strconv"
	"strings"
	"time"

	"github.com/hkjang/igame/migrations"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"golang.org/x/crypto/bcrypt"
)

func Open(ctx context.Context, dsn string) (*pgxpool.Pool, error) {
	config, err := pgxpool.ParseConfig(dsn)
	if err != nil {
		return nil, fmt.Errorf("parse postgres DSN: %w", err)
	}
	config.MaxConns = 20
	config.MinConns = 2
	config.MaxConnLifetime = 30 * time.Minute
	config.MaxConnIdleTime = 5 * time.Minute
	pool, err := pgxpool.NewWithConfig(ctx, config)
	if err != nil {
		return nil, fmt.Errorf("open postgres: %w", err)
	}
	if err := pool.Ping(ctx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("ping postgres: %w", err)
	}
	return pool, nil
}

// migrationFileName is the convention every schema migration follows: a
// zero-padded number, an underscore, a lower-case name, then ".sql".
var migrationFileName = regexp.MustCompile(`^([0-9]+)_[a-z0-9_]+\.sql$`)

// migrationNames lists the schema migrations in the order they must be applied.
//
// The files are ordered by their number rather than by their name. Sorting the
// names agrees with the numbers only while every number is padded to the same
// width, so the moment a "10_x.sql" joined the existing "001_".."009_" it would
// sort second and try to alter tables that do not exist yet — against a live
// database, halfway through a deployment. Sorting on the parsed number instead
// keeps the order the numbers describe no matter how they are written.
//
// A name that does not follow the convention, or a number used twice, is
// refused rather than applied at a guessed position: the files are compiled in,
// so this is a mistake in the repository that every start-up should report the
// same way instead of one that depends on the file system.
func migrationNames(fsys fs.FS) ([]string, error) {
	entries, err := fs.ReadDir(fsys, ".")
	if err != nil {
		return nil, err
	}
	type migration struct {
		number int
		name   string
	}
	found := make([]migration, 0, len(entries))
	seen := make(map[int]string, len(entries))
	for _, entry := range entries {
		name := entry.Name()
		if entry.IsDir() || !strings.HasSuffix(name, ".sql") {
			continue
		}
		match := migrationFileName.FindStringSubmatch(name)
		if match == nil {
			return nil, fmt.Errorf("migration %s is not named <number>_<name>.sql", name)
		}
		number, err := strconv.Atoi(match[1])
		if err != nil {
			return nil, fmt.Errorf("migration %s has an unreadable number: %w", name, err)
		}
		if other, duplicate := seen[number]; duplicate {
			return nil, fmt.Errorf("migrations %s and %s share the number %d", other, name, number)
		}
		seen[number] = name
		found = append(found, migration{number: number, name: name})
	}
	sort.Slice(found, func(i, j int) bool { return found[i].number < found[j].number })
	names := make([]string, 0, len(found))
	for _, entry := range found {
		names = append(names, entry.name)
	}
	return names, nil
}

func Migrate(ctx context.Context, pool *pgxpool.Pool) error {
	if _, err := pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS schema_migrations (
		name text PRIMARY KEY, checksum text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now())`); err != nil {
		return fmt.Errorf("create schema migrations table: %w", err)
	}
	names, err := migrationNames(migrations.Files)
	if err != nil {
		return err
	}
	for _, name := range names {
		body, err := migrations.Files.ReadFile(name)
		if err != nil {
			return err
		}
		checksum := fmt.Sprintf("%x", sha256.Sum256(body))
		var existing string
		err = pool.QueryRow(ctx, `SELECT checksum FROM schema_migrations WHERE name=$1`, name).Scan(&existing)
		if err == nil {
			if existing != checksum {
				return fmt.Errorf("migration %s checksum changed", name)
			}
			continue
		}
		if err != pgx.ErrNoRows {
			return fmt.Errorf("read migration %s state: %w", name, err)
		}
		tx, err := pool.Begin(ctx)
		if err != nil {
			return err
		}
		if _, err = tx.Exec(ctx, string(body)); err == nil {
			_, err = tx.Exec(ctx, `INSERT INTO schema_migrations(name,checksum) VALUES($1,$2)`, name, checksum)
		}
		if err != nil {
			_ = tx.Rollback(ctx)
			return fmt.Errorf("apply migration %s: %w", name, err)
		}
		if err := tx.Commit(ctx); err != nil {
			return fmt.Errorf("commit migration %s: %w", name, err)
		}
	}
	return nil
}

// EnsureBootstrapAdmin creates the first local administrator. It intentionally
// does not overwrite a password later changed through the administrator UI.
func EnsureBootstrapAdmin(ctx context.Context, pool *pgxpool.Pool, username, password string) error {
	hash, err := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	if err != nil {
		return err
	}
	_, err = pool.Exec(ctx, `INSERT INTO users(username,display_name,password_hash,role,status)
		VALUES($1,$1,$2,'admin','active') ON CONFLICT(username) DO UPDATE SET
		password_hash=CASE WHEN users.password_hash='' THEN excluded.password_hash ELSE users.password_hash END,
		role='admin',status='active',updated_at=now()`, username, string(hash))
	if err != nil {
		return fmt.Errorf("ensure bootstrap administrator: %w", err)
	}
	return nil
}
package database

import (
	"strconv"
	"strings"
	"testing"
	"testing/fstest"

	"github.com/hkjang/igame/migrations"
)

func sqlFiles(names ...string) fstest.MapFS {
	files := fstest.MapFS{}
	for _, name := range names {
		files[name] = &fstest.MapFile{Data: []byte("SELECT 1;")}
	}
	return files
}

// The migrations are applied in the order they are numbered, and the tenth one
// is where sorting the names stops agreeing with that: "10_" sorts before
// "002_". Applying a brand new migration second, against a database that is
// already live, is a broken deployment that only happens once the tenth file
// exists.
func TestATenthMigrationIsAppliedAfterTheNinthAndNotSecond(t *testing.T) {
	names, err := migrationNames(sqlFiles("001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"))
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	want := []string{"001_initial.sql", "002_extended.sql", "009_receipt_clock.sql", "10_battle_audit.sql", "11_later.sql"}
	if strings.Join(names, ",") != strings.Join(want, ",") {
		t.Fatalf("migrations run as %v, want %v", names, want)
	}
}

// Two branches that each add "010_" merge cleanly and leave the order of the
// two schema changes up to whatever the file system reports first. Refusing to
// start says so once instead of applying them differently on different hosts.
func TestTwoMigrationsSharingANumberAreRefused(t *testing.T) {
	_, err := migrationNames(sqlFiles("001_initial.sql", "010_ranking.sql", "010_replay.sql"))
	if err == nil {
		t.Fatal("two migrations numbered 010 were accepted; their order is left to the file system")
	}
	if !strings.Contains(err.Error(), "010_ranking.sql") || !strings.Contains(err.Error(), "010_replay.sql") {
		t.Fatalf("the error does not name both files: %v", err)
	}
}

// A file that carries no number has no place in the sequence, so guessing one
// would apply it at an arbitrary point. It is reported instead.
func TestAMigrationWithoutANumberIsRefused(t *testing.T) {
	for _, name := range []string{"initial.sql", "v2_extended.sql", "003 realmguard.sql"} {
		if _, err := migrationNames(sqlFiles("001_initial.sql", name)); err == nil {
			t.Fatalf("%q was accepted as a migration despite not being numbered", name)
		}
	}
}

// Only the .sql files are schema migrations; migrations.go lives beside them.
func TestNonSQLFilesAreNotTreatedAsMigrations(t *testing.T) {
	files := sqlFiles("001_initial.sql")
	files["migrations.go"] = &fstest.MapFile{Data: []byte("package migrations")}
	files["README.md"] = &fstest.MapFile{Data: []byte("# schema")}
	names, err := migrationNames(files)
	if err != nil {
		t.Fatalf("migrationNames: %v", err)
	}
	if len(names) != 1 || names[0] != "001_initial.sql" {
		t.Fatalf("migrations are %v, want only 001_initial.sql", names)
	}
}

// The shipped migrations have to satisfy the convention the loader enforces,
// and their numbers have to run 1, 2, 3 ... with no gap: a gap means a file
// that a deployed database has already applied went missing from the tree.
func TestTheShippedMigrationsAreNumberedFromOneWithoutGaps(t *testing.T) {
	names, err := migrationNames(migrations.Files)
	if err != nil {
		t.Fatalf("the shipped migrations do not follow the naming convention: %v", err)
	}
	if len(names) == 0 {
		t.Fatal("no migrations are embedded; a fresh database would come up with no schema")
	}
	for i, name := range names {
		number, err := strconv.Atoi(migrationFileName.FindStringSubmatch(name)[1])
		if err != nil {
			t.Fatalf("migration %s has an unreadable number: %v", name, err)
		}
		if number != i+1 {
			t.Fatalf("migration %s is numbered %d but sits at position %d; a migration is missing", name, number, i+1)
		}
	}
}
// Package config loads igame's deliberately small bootstrap configuration.
// All mutable service configuration is stored in PostgreSQL.
package config

import (
	"encoding/base64"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"strings"
	"unicode/utf8"
)

const (
	EnvPostgresDSN        = "POSTGRES_DSN"
	EnvBootstrapAdmin     = "BOOTSTRAP_ADMIN"
	EnvBootstrapAdminPass = "BOOTSTRAP_ADMIN_PASSWORD"
	EnvEncryptionKey      = "ENCRYPTION_KEY"
)

type Config struct {
	PostgresDSN       string
	BootstrapAdmin    string
	BootstrapPassword string
	EncryptionKey     []byte
}

func Load() (Config, error) {
	c := Config{
		PostgresDSN:       strings.TrimSpace(os.Getenv(EnvPostgresDSN)),
		BootstrapAdmin:    strings.TrimSpace(os.Getenv(EnvBootstrapAdmin)),
		BootstrapPassword: os.Getenv(EnvBootstrapAdminPass),
	}
	var missing []string
	if c.PostgresDSN == "" {
		missing = append(missing, EnvPostgresDSN)
	}
	if c.BootstrapAdmin == "" {
		missing = append(missing, EnvBootstrapAdmin)
	}
	if c.BootstrapPassword == "" {
		missing = append(missing, EnvBootstrapAdminPass)
	}
	keyText := strings.TrimSpace(os.Getenv(EnvEncryptionKey))
	if keyText == "" {
		missing = append(missing, EnvEncryptionKey)
	}
	if len(missing) != 0 {
		return Config{}, fmt.Errorf("missing required environment variables: %s", strings.Join(missing, ", "))
	}
	if utf8.RuneCountInString(c.BootstrapPassword) < 12 {
		return Config{}, fmt.Errorf("%s must be at least 12 characters", EnvBootstrapAdminPass)
	}
	key, err := ParseEncryptionKey(keyText)
	if err != nil {
		return Config{}, fmt.Errorf("%s: %w", EnvEncryptionKey, err)
	}
	c.EncryptionKey = key
	return c, nil
}

func ParseEncryptionKey(value string) ([]byte, error) {
	if strings.HasPrefix(value, "base64:") {
		b, err := base64.StdEncoding.DecodeString(strings.TrimPrefix(value, "base64:"))
		if err != nil {
			return nil, errors.New("invalid base64 value")
		}
		return validateKey(b)
	}
	if strings.HasPrefix(value, "hex:") {
		b, err := hex.DecodeString(strings.TrimPrefix(value, "hex:"))
		if err != nil {
			return nil, errors.New("invalid hex value")
		}
		return validateKey(b)
	}
	// A plain 32-byte value keeps first-time offline installation simple.
	return validateKey([]byte(value))
}

func validateKey(key []byte) ([]byte, error) {
	if len(key) != 32 {
		return nil, fmt.Errorf("must decode to exactly 32 bytes, got %d", len(key))
	}
	return append([]byte(nil), key...), nil
}
